/* Stumme Karte Europa — a blind map of Europe to drag names onto.
 *
 * The map is a silent one on purpose: it carries outlines, rivers, mountain
 * ridges, capital dots and landmark squares, and not a single name. Names
 * arrive one at a time, as chips the player drops where they belong, and a
 * name that lands correctly stays on the map. Filling the map is the lesson.
 *
 * Mounted on <div class="ebm" data-map="/media/europe-blind-map/map.json">.
 * The geometry in that file is generated by tools/build_europe_map.py and is
 * already projected into the SVG coordinate system, so nothing here has to
 * know about latitudes.
 *
 * No dependencies, no network traffic beyond the one map file, no analytics.
 */
(function () {
  "use strict";

  var ROUND_SIZE = 5;
  var STORE_KEY = "ebm.learned.v2";
  var LANG_KEY = "lang";
  var DRAG_SLOP = 6;          // px of movement before a tap becomes a drag

  // ------------------------------------------------------------------ text

  var TEXT = {
    de: {
      lead: "Zieh die fünf Namen an die richtige Stelle.",
      leadTap: "Tippe einen Namen an und dann die Karte.",
      category: "Thema",
      level: "Stufe",
      levels: ["Leicht", "Mittel", "Alles"],
      next: "Nächste fünf",
      show: "Zeig es mir",
      reset: "Fortschritt löschen",
      resetAsk: "Allen Lernfortschritt löschen?",
      learned: "gelernt",
      correct: "Richtig!",
      close: "Ganz nah — versuch es noch einmal.",
      wrong: "Daneben. Versuch es noch einmal.",
      wrongWater: "Das ist Land. Ein Meer liegt im Wasser.",
      wrongLand: "Das ist Wasser. Such die Landfläche.",
      shown: "Hier liegt es.",
      doneAll: "Alle %d richtig. Stark!",
      done: "%d von %d richtig.",
      empty: "Für dieses Thema und diese Stufe gibt es nichts mehr. Wähle etwas anderes.",
      legend: "Punkt = Hauptstadt · Quadrat = Sehenswürdigkeit · blaue Linie = Fluss · braune Linie = Gebirge",
      keyHint: "Mit der Tastatur: Namen mit Tab und Enter wählen, dann mit den Pfeiltasten das Kreuz bewegen und mit Enter ablegen.",
      loading: "Karte wird geladen …",
      failed: "Die Karte konnte nicht geladen werden.",
      cats: {
        all: "Alles", country: "Länder", capital: "Hauptstädte",
        water: "Meere & Ozeane", river: "Flüsse", mountain: "Gebirge",
        landform: "Inseln & Halbinseln", site: "Sehenswürdigkeiten"
      }
    },
    en: {
      lead: "Drag the five names to the right place.",
      leadTap: "Tap a name, then tap the map.",
      category: "Topic",
      level: "Level",
      levels: ["Easy", "Medium", "Everything"],
      next: "Next five",
      show: "Show me",
      reset: "Clear progress",
      resetAsk: "Clear all learning progress?",
      learned: "learned",
      correct: "Correct!",
      close: "Very close. Try again.",
      wrong: "Not there. Try again.",
      wrongWater: "That is land. A sea is water.",
      wrongLand: "That is water. Find the land.",
      shown: "Here it is.",
      doneAll: "All %d right. Well done!",
      done: "%d out of %d right.",
      empty: "Nothing left for this topic and level. Pick another one.",
      legend: "dot = capital · square = landmark · blue line = river · brown line = mountain range",
      keyHint: "By keyboard: choose a name with Tab and Enter, move the cross with the arrow keys, drop it with Enter.",
      loading: "Loading the map …",
      failed: "The map could not be loaded.",
      cats: {
        all: "Everything", country: "Countries", capital: "Capitals",
        water: "Seas & oceans", river: "Rivers", mountain: "Mountain ranges",
        landform: "Islands & peninsulas", site: "Landmarks"
      }
    }
  };

  var CAT_ORDER = ["all", "country", "capital", "water", "river",
                   "mountain", "landform", "site"];

  // ------------------------------------------------------------------- CSS

  var CSS = [
    ".ebm{border:1px solid var(--rule,#ccc);border-radius:12px;padding:1rem 1.1rem 1.2rem;margin:1.6rem 0;background:var(--surface,#fff)}",
    ".ebm__bar{display:flex;flex-wrap:wrap;gap:0.5rem 1rem;align-items:center;margin:0 0 0.8rem}",
    ".ebm__group{display:flex;flex-wrap:wrap;gap:0.3rem;align-items:center}",
    ".ebm__glabel{font-size:0.78em;letter-spacing:0.04em;text-transform:uppercase;color:var(--muted,#777)}",
    ".ebm__opt{border:1px solid var(--rule-strong,#bbb);background:transparent;color:var(--ink,#222);border-radius:999px;padding:0.22rem 0.7rem;font:inherit;font-size:0.84em;cursor:pointer}",
    ".ebm__opt:hover{border-color:var(--accent,#b4620e)}",
    ".ebm__opt[aria-pressed=true]{background:var(--accent-wash,#f7ead9);border-color:var(--accent,#b4620e);color:var(--accent,#b4620e);font-weight:600}",
    ".ebm__spacer{flex:1 1 auto}",
    ".ebm__score{font-size:0.84em;color:var(--muted,#666);white-space:nowrap}",
    ".ebm__lead{margin:0 0 0.7rem;font-weight:600}",
    ".ebm__mapwrap{position:relative;border-radius:10px;overflow:hidden;background:#cfe2f3}",
    ".ebm__map{display:block;width:100%;height:auto;touch-action:manipulation}",
    ".ebm__map:focus-visible{outline:3px solid var(--accent,#b4620e);outline-offset:-3px}",
    ".ebm__sea{fill:#cfe2f3}",
    ".ebm__land{fill:#fbf4e6;stroke:#97a5b2;stroke-width:0.7;stroke-linejoin:round}",
    ".ebm__land--ctx{fill:#e2e6e9;stroke:#c3cad1;stroke-width:0.5}",
    ".ebm__land--hit{fill:#f6d9b4}",
    ".ebm__lake{fill:#cfe2f3;stroke:#9cc3e0;stroke-width:0.4}",
    ".ebm__river{fill:none;stroke:#79aed6;stroke-width:0.9;stroke-linejoin:round;stroke-linecap:round}",
    ".ebm__ridge{fill:none;stroke:#8d7b5b;stroke-width:3.4;stroke-linecap:round;opacity:0.6}",
    ".ebm__cap{fill:#b4620e}",
    ".ebm__site{fill:#3e3170}",
    ".ebm__hl{fill:none;stroke:#c0392b;stroke-width:3.2;stroke-linecap:round;stroke-linejoin:round}",
    ".ebm__ring{fill:none;stroke:#c0392b;stroke-width:2}",
    ".ebm__pin{fill:#1e8e3e}",
    ".ebm__pin--shown{fill:#c0392b}",
    ".ebm__name{font:600 11px/1 var(--font-body,system-ui),sans-serif;fill:#1b2733;paint-order:stroke;stroke:#fff;stroke-width:3.2;stroke-linejoin:round}",
    ".ebm__cross{stroke:#c0392b;stroke-width:1.6}",
    ".ebm__pulse{animation:ebmPulse 1.6s ease-out 2}",
    "@keyframes ebmPulse{0%,100%{opacity:1}50%{opacity:0.25}}",
    ".ebm__tray{display:flex;flex-wrap:wrap;gap:0.45rem;margin:0.9rem 0 0;min-height:2.2rem}",
    ".ebm__chip{border:1px solid var(--rule-strong,#bbb);background:var(--surface,#fff);color:var(--ink,#222);border-radius:999px;padding:0.4rem 0.9rem;font:inherit;font-size:0.95em;cursor:grab;touch-action:none;user-select:none}",
    ".ebm__chip:hover{border-color:var(--accent,#b4620e)}",
    ".ebm__chip[aria-pressed=true]{background:var(--accent,#b4620e);border-color:var(--accent,#b4620e);color:#fff}",
    ".ebm__chip--gone{visibility:hidden}",
    ".ebm__chip--shake{animation:ebmShake 0.3s}",
    "@keyframes ebmShake{25%{transform:translateX(-5px)}75%{transform:translateX(5px)}}",
    ".ebm__ghost{position:fixed;z-index:9999;pointer-events:none;border-radius:999px;padding:0.4rem 0.9rem;font-size:0.95em;background:var(--accent,#b4620e);color:#fff;box-shadow:0 4px 14px rgba(0,0,0,0.25);transform:translate(-50%,-150%)}",
    ".ebm__say{margin:0.8rem 0 0;min-height:1.5em;font-size:0.95em}",
    ".ebm__say--ok{color:#1e8e3e;font-weight:600}",
    ".ebm__say--no{color:#c0392b}",
    ".ebm__note{color:var(--muted,#666);font-weight:400}",
    ".ebm__foot{display:flex;flex-wrap:wrap;gap:0.5rem;align-items:center;margin:0.9rem 0 0}",
    ".ebm__go{border:none;border-radius:8px;background:var(--accent,#b4620e);color:#fff;padding:0.5rem 1.1rem;font:inherit;font-weight:600;cursor:pointer}",
    ".ebm__go:hover{background:var(--accent-lift,#8f4c09)}",
    ".ebm__legend{margin:0.7rem 0 0;font-size:0.8em;color:var(--muted,#666)}",
    // Everything drawn inside the SVG is in map units, so it shrinks with
    // the map. On a narrow screen the map is about a third of its design
    // width, which would leave the names at four pixels tall, so the
    // marks and the labels are scaled back up there.
    "@media (max-width:46rem){"
      + ".ebm__name{font-size:30px;stroke-width:7}"
      + ".ebm__cap{r:6}.ebm__pin{r:6}"
      + ".ebm__site{transform-box:fill-box;transform-origin:center;transform:scale(2)}"
      + ".ebm__ring{stroke-width:4}.ebm__hl{stroke-width:6}"
      + ".ebm__ridge{stroke-width:5}.ebm__cross{stroke-width:3.5}"
    + "}",
    "@media (max-width:30rem){.ebm{padding:0.8rem}.ebm__chip{font-size:0.9em;padding:0.35rem 0.7rem}}"
  ].join("");

  // -------------------------------------------------------------- plumbing

  function el(tag, cls, parent, text) {
    var node = document.createElement(tag);
    if (cls) node.className = cls;
    if (text !== undefined) node.textContent = text;
    if (parent) parent.appendChild(node);
    return node;
  }

  function svgEl(tag, attrs, parent) {
    var node = document.createElementNS("http://www.w3.org/2000/svg", tag);
    for (var key in attrs) {
      if (Object.prototype.hasOwnProperty.call(attrs, key)) {
        node.setAttribute(key, attrs[key]);
      }
    }
    if (parent) parent.appendChild(node);
    return node;
  }

  function shuffled(list) {
    var out = list.slice();
    for (var i = out.length - 1; i > 0; i -= 1) {
      var j = Math.floor(Math.random() * (i + 1));
      var tmp = out[i];
      out[i] = out[j];
      out[j] = tmp;
    }
    return out;
  }

  function readStore() {
    try {
      return JSON.parse(localStorage.getItem(STORE_KEY)) || {};
    } catch (e) {
      return {};
    }
  }

  function writeStore(value) {
    try {
      localStorage.setItem(STORE_KEY, JSON.stringify(value));
    } catch (e) { /* private window, quota, blocked storage: play on anyway */ }
  }

  function initialLang() {
    try {
      var stored = localStorage.getItem(LANG_KEY);
      if (stored === "de" || stored === "en") return stored;
    } catch (e) { /* ignore */ }
    var tag = (navigator.language || "de").slice(0, 2);
    return tag === "en" ? "en" : "de";
  }

  // --------------------------------------------------------------- geometry

  function distance(ax, ay, bx, by) {
    return Math.hypot(ax - bx, ay - by);
  }

  function distanceToSegment(px, py, ax, ay, bx, by) {
    var dx = bx - ax;
    var dy = by - ay;
    var len = dx * dx + dy * dy;
    var t = len === 0 ? 0 : ((px - ax) * dx + (py - ay) * dy) / len;
    t = Math.max(0, Math.min(1, t));
    return distance(px, py, ax + t * dx, ay + t * dy);
  }

  /* A [null, null] entry in the point list is a pen lift between two branches
     of the same river, so no segment is measured across it. */
  function distanceToPath(px, py, points) {
    var best = Infinity;
    for (var i = 1; i < points.length; i += 1) {
      var a = points[i - 1];
      var b = points[i];
      if (a[0] === null || b[0] === null) continue;
      var d = distanceToSegment(px, py, a[0], a[1], b[0], b[1]);
      if (d < best) best = d;
    }
    return best;
  }

  // ------------------------------------------------------------------ game

  function Game(mount, data) {
    this.mount = mount;
    this.data = data;
    this.lang = initialLang();
    this.category = "all";
    this.level = 1;
    this.learned = readStore();
    this.selected = null;
    this.drag = null;
    this.cursor = null;
    this.shapeById = {};
    this.landPaths = [];
    this.build();
    this.newRound();
  }

  Game.prototype.t = function () {
    return TEXT[this.lang];
  };

  Game.prototype.name = function (item) {
    return item[this.lang];
  };

  Game.prototype.note = function (item) {
    return item[this.lang === "de" ? "nde" : "nen"] || "";
  };

  // ----------------------------------------------------------- chrome

  Game.prototype.build = function () {
    var self = this;
    this.mount.innerHTML = "";
    this.mount.classList.add("ebm");

    var bar = el("div", "ebm__bar", this.mount);

    var catGroup = el("div", "ebm__group", bar);
    el("span", "ebm__glabel", catGroup, "");
    this.catLabel = catGroup.firstChild;
    this.catButtons = {};
    CAT_ORDER.forEach(function (id) {
      var button = el("button", "ebm__opt", catGroup, "");
      button.type = "button";
      button.addEventListener("click", function () {
        self.category = id;
        self.newRound();
      });
      self.catButtons[id] = button;
    });

    var levelGroup = el("div", "ebm__group", bar);
    this.levelLabel = el("span", "ebm__glabel", levelGroup, "");
    this.levelButtons = [];
    [1, 2, 3].forEach(function (value, index) {
      var button = el("button", "ebm__opt", levelGroup, "");
      button.type = "button";
      button.addEventListener("click", function () {
        self.level = value;
        self.newRound();
      });
      self.levelButtons[index] = button;
    });

    el("span", "ebm__spacer", bar);

    var langGroup = el("div", "ebm__group", bar);
    this.langButtons = {};
    ["de", "en"].forEach(function (code) {
      var button = el("button", "ebm__opt", langGroup, code.toUpperCase());
      button.type = "button";
      button.addEventListener("click", function () {
        self.lang = code;
        try { localStorage.setItem(LANG_KEY, code); } catch (e) { /* ignore */ }
        self.retext();
        self.newRound();
      });
      self.langButtons[code] = button;
    });
    this.score = el("span", "ebm__score", bar, "");

    this.lead = el("p", "ebm__lead", this.mount, "");
    this.wrap = el("div", "ebm__mapwrap", this.mount);
    this.buildMap();
    this.tray = el("div", "ebm__tray", this.mount);
    this.say = el("p", "ebm__say", this.mount, "");

    var foot = el("div", "ebm__foot", this.mount);
    this.showButton = el("button", "ebm__opt", foot, "");
    this.showButton.type = "button";
    this.showButton.addEventListener("click", function () { self.reveal(); });
    this.nextButton = el("button", "ebm__go", foot, "");
    this.nextButton.type = "button";
    this.nextButton.addEventListener("click", function () { self.newRound(); });
    this.resetButton = el("button", "ebm__opt", foot, "");
    this.resetButton.type = "button";
    this.resetButton.addEventListener("click", function () {
      if (!window.confirm(self.t().resetAsk)) return;
      self.learned = {};
      writeStore(self.learned);
      self.newRound();
    });

    this.legend = el("p", "ebm__legend", this.mount, "");
    this.retext();
  };

  Game.prototype.retext = function () {
    var t = this.t();
    var self = this;
    this.catLabel.textContent = t.category;
    CAT_ORDER.forEach(function (id) {
      self.catButtons[id].textContent = t.cats[id];
    });
    this.levelLabel.textContent = t.level;
    this.levelButtons.forEach(function (button, index) {
      button.textContent = t.levels[index];
    });
    this.showButton.textContent = t.show;
    this.nextButton.textContent = t.next;
    this.resetButton.textContent = t.reset;
    this.legend.textContent = t.legend + " — " + t.keyHint;
    this.map.setAttribute("aria-label",
      this.lang === "de" ? "Stumme Karte von Europa" : "Blind map of Europe");
  };

  // -------------------------------------------------------------- the map

  Game.prototype.buildMap = function () {
    var self = this;
    var data = this.data;
    var w = data.view[0];
    var h = data.view[1];

    var svg = svgEl("svg", {
      viewBox: "0 0 " + w + " " + h,
      "class": "ebm__map", role: "img", tabindex: "0"
    }, this.wrap);
    this.map = svg;

    svgEl("rect", { width: w, height: h, "class": "ebm__sea" }, svg);

    data.shapes.forEach(function (shape) {
      var path = svgEl("path", {
        d: shape.d,
        "class": "ebm__land" + (shape.q ? "" : " ebm__land--ctx")
      }, svg);
      self.landPaths.push(path);
      if (shape.q) self.shapeById[shape.id] = path;
    });

    svgEl("path", { d: data.lakes, "class": "ebm__lake" }, svg);
    svgEl("path", { d: data.rivers, "class": "ebm__river" }, svg);
    data.items.forEach(function (item) {
      if (item.cat === "river" && item.hl) {
        svgEl("path", { d: item.hl, "class": "ebm__river" }, svg);
      }
    });
    data.marks.ridge.forEach(function (ridge) {
      svgEl("polyline", {
        points: ridge.map(function (p) { return p[0] + "," + p[1]; }).join(" "),
        "class": "ebm__ridge"
      }, svg);
    });
    data.marks.capital.forEach(function (p) {
      svgEl("circle", { cx: p[0], cy: p[1], r: 3.1, "class": "ebm__cap" }, svg);
    });
    data.marks.site.forEach(function (p) {
      svgEl("rect", {
        x: p[0] - 2.4, y: p[1] - 2.4, width: 4.8, height: 4.8,
        "class": "ebm__site"
      }, svg);
    });

    this.answers = svgEl("g", {}, svg);   // cleared between rounds
    this.crossLayer = svgEl("g", {}, svg);

    svg.addEventListener("click", function (event) {
      if (!self.selected) return;
      var point = self.toMap(event.clientX, event.clientY);
      if (point) self.tryDrop(self.selected, point);
    });
    svg.addEventListener("keydown", function (event) {
      self.onMapKey(event);
    });
  };

  /* Screen coordinates to map units. getScreenCTM accounts for the viewBox,
     the CSS size and any page scaling, which a rect-based calculation would
     have to reproduce by hand. */
  Game.prototype.toMap = function (clientX, clientY) {
    var ctm = this.map.getScreenCTM();
    if (!ctm) return null;
    var inverse = ctm.inverse();
    return {
      x: inverse.a * clientX + inverse.c * clientY + inverse.e,
      y: inverse.b * clientX + inverse.d * clientY + inverse.f
    };
  };

  Game.prototype.isOnLand = function (point) {
    if (!this.landPaths.length || !this.landPaths[0].isPointInFill) return null;
    var dom = new DOMPoint(point.x, point.y);
    for (var i = 0; i < this.landPaths.length; i += 1) {
      if (this.landPaths[i].isPointInFill(dom)) return true;
    }
    return false;
  };

  // ------------------------------------------------------------ the round

  Game.prototype.pool = function () {
    var self = this;
    return this.data.items.filter(function (item) {
      if (self.category !== "all" && item.cat !== self.category) return false;
      return item.tier <= self.level;
    });
  };

  /* Items the player has never placed come first, so a round is new ground
     before it is revision, and a long session still ends up covering the map. */
  Game.prototype.pickRound = function () {
    var self = this;
    var pool = shuffled(this.pool());
    pool.sort(function (a, b) {
      return (self.learned[a.id] || 0) - (self.learned[b.id] || 0);
    });
    var head = pool.slice(0, Math.min(ROUND_SIZE * 3, pool.length));
    return shuffled(head).slice(0, ROUND_SIZE);
  };

  Game.prototype.newRound = function () {
    this.round = this.pickRound();
    this.tries = {};
    this.done = 0;
    this.firstTry = 0;
    this.selected = null;
    this.cursor = null;
    this.answers.innerHTML = "";
    this.crossLayer.innerHTML = "";
    this.clearHighlights();
    this.renderChrome();
    this.renderTray();
    this.say.className = "ebm__say";
    this.say.textContent = this.round.length ? this.t().lead : this.t().empty;
  };

  Game.prototype.renderChrome = function () {
    var self = this;
    CAT_ORDER.forEach(function (id) {
      self.catButtons[id].setAttribute("aria-pressed", id === self.category);
    });
    this.levelButtons.forEach(function (button, index) {
      button.setAttribute("aria-pressed", index + 1 === self.level);
    });
    ["de", "en"].forEach(function (code) {
      self.langButtons[code].setAttribute("aria-pressed", code === self.lang);
    });
    var total = this.data.items.length;
    var known = 0;
    for (var id in this.learned) {
      if (Object.prototype.hasOwnProperty.call(this.learned, id)) known += 1;
    }
    this.score.textContent = known + " / " + total + " " + this.t().learned;
    this.lead.textContent = this.round.length
      ? (window.matchMedia && window.matchMedia("(pointer: coarse)").matches
         ? this.t().leadTap : this.t().lead)
      : "";
  };

  Game.prototype.renderTray = function () {
    var self = this;
    this.tray.innerHTML = "";
    this.chips = {};
    this.round.forEach(function (item) {
      var chip = el("button", "ebm__chip", self.tray, self.name(item));
      chip.type = "button";
      chip.setAttribute("aria-pressed", "false");
      self.chips[item.id] = chip;
      chip.addEventListener("pointerdown", function (event) {
        self.onChipDown(event, item, chip);
      });
      chip.addEventListener("click", function (event) {
        event.preventDefault();
        self.select(item);
      });
    });
  };

  Game.prototype.select = function (item) {
    var self = this;
    this.selected = this.selected === item ? null : item;
    Object.keys(this.chips).forEach(function (id) {
      self.chips[id].setAttribute("aria-pressed", String(
        !!self.selected && self.selected.id === id));
    });
    if (this.selected) {
      this.showCross(this.cursor || { x: this.data.view[0] / 2,
                                      y: this.data.view[1] / 2 });
    } else {
      this.crossLayer.innerHTML = "";
    }
  };

  // --------------------------------------------------------------- drag

  Game.prototype.onChipDown = function (event, item, chip) {
    var self = this;
    if (event.button !== undefined && event.button !== 0) return;
    this.drag = {
      item: item, chip: chip, id: event.pointerId,
      x0: event.clientX, y0: event.clientY, ghost: null
    };
    try { chip.setPointerCapture(event.pointerId); } catch (e) { /* ignore */ }

    function move(moveEvent) {
      if (!self.drag || moveEvent.pointerId !== self.drag.id) return;
      var moved = distance(moveEvent.clientX, moveEvent.clientY,
                           self.drag.x0, self.drag.y0);
      if (!self.drag.ghost && moved < DRAG_SLOP) return;
      if (!self.drag.ghost) {
        self.drag.ghost = el("div", "ebm__ghost", document.body,
                             self.name(self.drag.item));
      }
      self.drag.ghost.style.left = moveEvent.clientX + "px";
      self.drag.ghost.style.top = moveEvent.clientY + "px";
      moveEvent.preventDefault();
    }

    function up(upEvent) {
      if (!self.drag || upEvent.pointerId !== self.drag.id) return;
      var drag = self.drag;
      self.drag = null;
      chip.removeEventListener("pointermove", move);
      chip.removeEventListener("pointerup", up);
      chip.removeEventListener("pointercancel", up);
      if (!drag.ghost) return;             // a tap: the click handler selects
      drag.ghost.remove();
      var rect = self.map.getBoundingClientRect();
      if (upEvent.clientX < rect.left || upEvent.clientX > rect.right
          || upEvent.clientY < rect.top || upEvent.clientY > rect.bottom) {
        return;
      }
      var point = self.toMap(upEvent.clientX, upEvent.clientY);
      if (point) self.tryDrop(drag.item, point);
    }

    chip.addEventListener("pointermove", move);
    chip.addEventListener("pointerup", up);
    chip.addEventListener("pointercancel", up);
  };

  // ------------------------------------------------------------ keyboard

  Game.prototype.showCross = function (point) {
    this.cursor = point;
    this.crossLayer.innerHTML = "";
    var size = 11;
    svgEl("line", { x1: point.x - size, y1: point.y, x2: point.x + size,
                    y2: point.y, "class": "ebm__cross" }, this.crossLayer);
    svgEl("line", { x1: point.x, y1: point.y - size, x2: point.x,
                    y2: point.y + size, "class": "ebm__cross" }, this.crossLayer);
  };

  Game.prototype.onMapKey = function (event) {
    if (!this.selected) return;
    var step = event.shiftKey ? 24 : 6;
    var point = this.cursor || { x: this.data.view[0] / 2,
                                 y: this.data.view[1] / 2 };
    var moved = { x: point.x, y: point.y };
    if (event.key === "ArrowLeft") moved.x -= step;
    else if (event.key === "ArrowRight") moved.x += step;
    else if (event.key === "ArrowUp") moved.y -= step;
    else if (event.key === "ArrowDown") moved.y += step;
    else if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      this.tryDrop(this.selected, point);
      return;
    } else {
      return;
    }
    event.preventDefault();
    moved.x = Math.max(0, Math.min(this.data.view[0], moved.x));
    moved.y = Math.max(0, Math.min(this.data.view[1], moved.y));
    this.showCross(moved);
  };

  // ----------------------------------------------------------- the answer

  /* Returns how far the drop is from the target, in map units, and whether it
     counts. A country is hit by falling inside it; a country too small to hit
     on a phone also accepts a drop near its label point. */
  Game.prototype.judge = function (item, point) {
    var target = item.t;
    if (target.k === "poly") {
      var shape = this.shapeById[target.ref];
      var inside = false;
      if (shape && shape.isPointInFill) {
        inside = shape.isPointInFill(new DOMPoint(point.x, point.y));
      }
      var near = distance(point.x, point.y, item.lab[0], item.lab[1]);
      var slack = target.a < 400 ? 11 : 0;
      return { ok: inside || near <= slack, far: inside ? 0 : near, side: null };
    }
    if (target.k === "line") {
      var d = distanceToPath(point.x, point.y, target.pts);
      return { ok: d <= target.r, far: d, side: null };
    }
    var dist = distance(point.x, point.y, target.x, target.y);
    var side = null;
    if (target.on) {
      var onLand = this.isOnLand(point);
      if (onLand !== null && onLand !== (target.on === "land")) {
        side = target.on;
      }
    }
    return { ok: dist <= target.r && !side, far: dist, side: side };
  };

  Game.prototype.tryDrop = function (item, point) {
    var verdict = this.judge(item, point);
    var t = this.t();
    this.tries[item.id] = (this.tries[item.id] || 0) + 1;

    if (verdict.ok) {
      if (this.tries[item.id] === 1) this.firstTry += 1;
      this.learned[item.id] = (this.learned[item.id] || 0) + 1;
      writeStore(this.learned);
      this.settle(item, true);
      this.tell(t.correct, "ok", item);
      return;
    }

    var chip = this.chips[item.id];
    if (chip) {
      chip.classList.remove("ebm__chip--shake");
      void chip.offsetWidth;
      chip.classList.add("ebm__chip--shake");
    }
    var tolerance = item.t.k === "pt" ? item.t.r : 14;
    var message = verdict.side === "water" ? t.wrongWater
      : verdict.side === "land" ? t.wrongLand
      : verdict.far < tolerance * 2.5 ? t.close : t.wrong;
    this.tell(message, "no", null);
  };

  Game.prototype.reveal = function () {
    var item = this.selected || this.round.filter(function (candidate) {
      return !candidate.__done;
    })[0];
    if (!item) return;
    this.settle(item, false);
    this.tell(this.t().shown, "no", item);
  };

  /* Pins the name on the map and marks the thing it belongs to. The map keeps
     every name that has been placed, so the blind map fills in as you go. */
  Game.prototype.settle = function (item, correct) {
    if (item.__done) return;
    item.__done = true;
    this.done += 1;

    if (item.t.k === "poly") {
      var shape = this.shapeById[item.t.ref];
      if (shape) shape.classList.add("ebm__land--hit");
    } else if (item.hl) {
      svgEl("path", { d: item.hl, "class": "ebm__hl" }, this.answers);
    } else {
      svgEl("circle", {
        cx: item.t.x, cy: item.t.y, r: Math.min(item.t.r, 16),
        "class": "ebm__ring"
      }, this.answers);
    }

    var x = item.lab[0];
    var y = item.lab[1];
    svgEl("circle", {
      cx: x, cy: y, r: 2.6,
      "class": "ebm__pin" + (correct ? "" : " ebm__pin--shown")
    }, this.answers);
    var text = svgEl("text", {
      x: x, y: y - 6, "class": "ebm__name", "text-anchor": "middle"
    }, this.answers);
    text.textContent = this.name(item);

    var chip = this.chips[item.id];
    if (chip) chip.classList.add("ebm__chip--gone");
    this.selected = null;
    this.crossLayer.innerHTML = "";
    this.renderChrome();

    if (this.done === this.round.length) this.finish();
  };

  Game.prototype.clearHighlights = function () {
    var self = this;
    Object.keys(this.shapeById).forEach(function (id) {
      self.shapeById[id].classList.remove("ebm__land--hit");
    });
    (this.round || []).forEach(function (item) { delete item.__done; });
  };

  Game.prototype.tell = function (message, kind, item) {
    this.say.className = "ebm__say ebm__say--" + kind;
    this.say.textContent = message;
    if (item) {
      var note = this.note(item);
      var line = this.name(item) + (note ? " — " + note : "");
      var span = el("span", "ebm__note", this.say, " " + line);
      span.setAttribute("aria-live", "polite");
    }
  };

  Game.prototype.finish = function () {
    var t = this.t();
    var message = this.firstTry === this.round.length
      ? t.doneAll.replace("%d", this.round.length)
      : t.done.replace("%d", this.firstTry).replace("%d", this.round.length);
    this.say.className = "ebm__say ebm__say--ok";
    this.say.textContent = message;
    this.nextButton.focus();
  };

  // ------------------------------------------------------------------ boot

  function mountAll() {
    var mounts = document.querySelectorAll(".ebm[data-map]");
    if (!mounts.length) return;
    var style = document.createElement("style");
    style.textContent = CSS;
    document.head.appendChild(style);

    Array.prototype.forEach.call(mounts, function (mount) {
      mount.textContent = TEXT[initialLang()].loading;
      fetch(mount.getAttribute("data-map"))
        .then(function (response) {
          if (!response.ok) throw new Error(response.status);
          return response.json();
        })
        .then(function (data) {
          var game = new Game(mount, data);
          if (window.__EBM_TEST__) window.__EBM_TEST__.game = game;
        })
        .catch(function () {
          mount.textContent = TEXT[initialLang()].failed;
        });
    });
  }

  // Test hook, inert on the live page. tools/map_proof.html sets
  // window.__EBM_TEST__ before this file loads and then builds a game from
  // its own copy of the data, which lets every target be checked against
  // isPointInFill -- the one part of the hit test that only exists in a
  // browser.
  if (window.__EBM_TEST__) {
    window.__EBM_TEST__ = { Game: Game, game: null, css: CSS };
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", mountAll);
  } else {
    mountAll();
  }
}());
